{
  "decline_reason": "",
  "claims": [
    {
      "text": "The supplied passages do not expressly resolve whether an application may be filed in a business name, or whether a business name itself qualifies for registration as a certification trade mark.",
      "quotes": [],
      "authority": "none"
    },
    {
      "text": "Under section 169, a certification trade mark distinguishes goods or services certified in relation to quality, accuracy or another characteristic from goods or services not so certified.",
      "quotes": [
        {
          "ref": "TMA1995/s169",
          "quote": "A certification trade mark is a sign used, or intended to be used, to distinguish goods or services: (a) dealt with or provided in the course of trade; and (b) certified by a person (owner of the certification trade mark), or by another person approved by that person, in relation to quality, accuracy or some other characteristic, including (in the case of goods) origin, material or mode of manufacture; from other goods or services dealt with or provided in the course of trade but not so certified."
        }
      ],
      "authority": "legislation"
    },
    {
      "text": "The Manual distinguishes certification from ordinary business identification: use of a certification trade mark on goods does not indicate who made or manufactured them.",
      "quotes": [
        {
          "ref": "TMM/Part35/1/1/5",
          "quote": "For example, use of a certification trade mark on goods does not indicate who made or manufactured the goods."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The Manual states that the registered owner has the exclusive right to use the certification trade mark and to allow others to use it, with the owner's use subject to the rules governing its use.",
      "quotes": [
        {
          "ref": "TMM/Part35/5#1~1",
          "quote": "5.1 A registered owner of a certification trade mark has the exclusive right to use, and to allow other persons to use, the certification trade mark. Use of a certification trade mark by the owner must be in accordance with the rules governing its use (section 171)."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The Manual calls a person whom the registered owner allows to use the mark an approved user, whose use must also comply with the rules.",
      "quotes": [
        {
          "ref": "TMM/Part35/5#1~1",
          "quote": "5.2 An approved user of a certification trade mark is a person who the registered owner has allowed to use the trade mark. The certification trade mark must be used in accordance with the rules governing its use (section 172)."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "Section 169 expressly permits the certified goods or services to be those of any person, including the owner or a person approved by the owner to certify goods or services.",
      "quotes": [
        {
          "ref": "TMA1995/s169",
          "quote": "Note: The goods or services certified may be those of any person, including the owner of the certification trade mark or any person approved by the owner for the purpose of certifying goods or services."
        }
      ],
      "authority": "legislation"
    },
    {
      "text": "The Manual requires the rules governing use to be assessed and approved by the ACCC before the certification trade mark can be accepted for registration.",
      "quotes": [
        {
          "ref": "TMM/Part35/1#1",
          "quote": "1.4 The rules governing use of a certification trade mark must be assessed and approved by the Australian Competition and Consumer Commission (Commission) before the trade mark can be accepted for registration."
        }
      ],
      "authority": "manual"
    }
  ],
  "declined": false,
  "concepts_used": [
    "GC-0107",
    "GC-0072",
    "GC-0084",
    "GC-0081",
    "GC-0133",
    "GC-0093"
  ]
}
